WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/30.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/30.0/apex.js")} 


var Contract = sforce.connection.query("SELECT id,Status,Standard_Contract__c from contract where id ='{!Opportunity.IME_ContractId__c}' limit 1"); 

ContractInfo = Contract.getArray("records"); 
var ContractStatus;
var StandardContract; 
var createContract=false;
var cancelContract=false;

if(ContractInfo[0] != null){ 
    ContractStatus= ContractInfo[0].Status; 
    StandardContract = ContractInfo[0].Standard_Contract__c;
} 
if(ContractStatus=='Activated')
{ 
    alert("There is an active contract already linked to this Opportunity"); 
}
else if(('{!Opportunity.Billing_Country__c}' != 'United Kingdom') &&
 ('{!Opportunity.Billing_Country__c}' != 'Ireland'))
{
    alert("This functionality can only be used when contracting in the UK or Ireland");

}
else if((StandardContract != 'true') && ('{!Opportunity.IME_Contract__c}'))
{
    alert("The contract linked haven't gone through the Standard Contract Process. Please contact Contracts Team to assist.");
}
else if (('{!Opportunity.Type}' != 'New Deal') || ('{!Opportunity.StageName}' != '4 - Negotiate')) { 
  alert("Standard Contracts can only be created for ’New Deal’ Opportunities at 'Stage 4 - Negotiate'"); 
} 
else if('{!Opportunity.IME_Contract__c}') 
{
	var r = confirm("There is a Contract already linked to this Opportunity, if you progress that contract will be cancelled"); 
    if(r == true) 
	{	
		createContract =true;
		cancelContract =true;
	}
}  
else
{ 
	createContract =true;
}

if(createContract)
{

  var r = confirm("Are you sure the contract is a Standard Contract and you have checked the followings? \n\n1. Verify companies house has been checked and used on the Opportunity \n2. Has the correct service and term been selected \n3. Address must be UK or Ireland if anything different do not proceed"); 
  if(r == true) 
  { 
	if(('{!JSENCODE(Opportunity.Company_Name__c)}' == '') || ('{!JSENCODE(Opportunity.Company_Registered_Address2__c)}' == '') || ('{!Opportunity.Company_Number__c}' == '') || ('{!Opportunity.Contract_Term__c}' == '' ) || ('{!Opportunity.Effective_Date__c}' == '' ) || ('{!Opportunity.Product__c}' == '' ) || ('{!Opportunity.Registered_In__c}' == '' )) 
	  {
		  alert("All fields in the 'Standard Contract Details' section should be populated"); 
	  }
	  else
	  {	
             var contractingCountry = '{!Opportunity.Contracting_Country__c}';
             var BillingCountry = '{!Opportunity.Billing_Country__c}';


			if(contractingCountry == BillingCountry){

			var signature = sforce.apex.execute("createNewContract","createStandardContract",{opportunityId:"{!Opportunity.Id}",UpdateContract:cancelContract}); 



		  var result = sforce.connection.query("Select product__c, Conga_Params__c,Country__c from IME_Contract_Conga_url__c"); 
		  records = result.getArray("records"); 
		  var conga_params=''; 
		  var oppProduct='{!Opportunity.Product__c}'; 

		  for (var i=0; i< records.length; i++) 
		  { 
			  if((records[i].Product__c== oppProduct) && (records[i].Country__c == contractingCountry)) 
			  { 
				  conga_params=records[i].Conga_Params__c; 
			  } 
		  } 
		 // alert(conga_params); 
		  window.open('https://composer.congamerge.com?sessionId={!API.Session_ID}&serverUrl={!API.Partner_Server_URL_290}&id={!Opportunity.Id}&AttachmentParentId='+signature+conga_params)&OCNR=1; 

		  window.location.reload(); 
	  }
	  else
	  {
		  alert('Billing Country needs to match with Contracting Country');
	  }
  } 
}
}
